// credits-portraits.js — die Portraits als Pixeldaten (Palettenbuchstaben).
// Erzeugt aus Rolands Upload-Ausschnitten (Ausschnitte in
// /opt/data/work/drr-tasks/portrait-vorlagen/ausgeschnitten/) mit
// portrait_konverter.py + erzeuge_daten.py: je Ausschnitt auf 96x96 gemittelt und
// auf die Spielpalette gezogen (naechste Farbe im CIELAB-Raum).
// CHENYAN stammt aus Rolands neuer Vorlage
// /opt/data/work/drr-tasks/V3-upload-portraits/quelle-chenyan-neu/chenyan-neu.jpg
// (sha256 606cd236739e888bc3b9a9b97c12e6290ffb5e6271b2419cb2af5bfe92c13eaf): linke
// Portraitflaeche x 0..720, y 1..667 (rechts vor Pfeil/App-UI abgeschnitten), mit 8 px
// hellem Rand als /opt/data/work/drr-tasks/portrait-vorlagen/ausgeschnitten-neu/chenyan.png
// abgelegt; Verfahren und Palette unveraendert, die neun anderen Ausschnitte ebenfalls.
// Bewusst keine PNG-Dateien im Repo: das Spiel soll auch per file:// ohne Server laufen.
// Buchstaben = Farben der Spielpalette (src/config.js PAL), " " = durchsichtig.
// Der helle Kachelhintergrund der Vorlagen ist durchsichtig gesetzt (Leerzeichen) —
// im dunklen Abspann darf keine helle Flaeche stehen.
import { PAL } from './config.js';

